import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { pathToFileURL } from 'node:url'

// Bundle the build decision and the existing security policy into the Worker.
// Do not depend on _headers being applied to a response generated by Worker code.
export async function writeIndexingPolicy(production) {
  const source = await readFile('public/_headers', 'utf8')
  const securityHeaders = Object.fromEntries(
    source
      .split('/_astro/*')[0]
      .split('\n')
      .flatMap((line) => {
        const match = line.match(/^\s+([^:]+):\s*(.+)$/)
        return match && match[1] !== 'X-Robots-Tag'
          ? [[match[1], match[2]]]
          : []
      }),
  )
  await mkdir('.astro', { recursive: true })
  await writeFile(
    '.astro/indexing-policy.json',
    JSON.stringify({ production, securityHeaders }),
  )
}
if (process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url)
  await writeIndexingPolicy(false)
